// Returns the course / interview-prep data stored on the user_jobs row for (auth_user_id, job_id).
const q = $('Webhook GET job-course').first().json.query || {};
const authUserId = String(q.auth_user_id ?? '').trim();
const jobId = String(q.job_id ?? '').trim();

if (!authUserId || !jobId) {
  return [{ json: { success: false, error: !authUserId ? 'missing_auth_user_id' : 'missing_job_id', auth_user_id: authUserId || null, job_id: jobId || null, courses: [] } }];
}

const row = $('Find User Job').all().map(i => i.json).find(r => r && r.job_id);
if (!row) {
  return [{ json: { success: false, error: 'user_job_not_found', auth_user_id: authUserId, job_id: jobId, courses: [] } }];
}

function parseArr(v) {
  if (v === null || v === undefined || v === '') return [];
  if (Array.isArray(v)) return v;
  try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; } catch (e) { return []; }
}

return [{ json: {
  success: true,
  auth_user_id: authUserId,
  job_id: row.job_id,
  user_job_id: row.id,
  status: row.status ?? null,
  match_score: row.match_score ?? null,
  priority_score: row.priority_score ?? null,
  matched_skills: parseArr(row.matched_skills_json),
  missing_skills: parseArr(row.missing_skills_json),
  prep_status: row.prep_status || 'not_ready',
  prep_role_type: row.prep_role_type ?? null,
  prep_data_quality: row.prep_data_quality ?? null,
  prep_updated_at: row.prep_updated_at ?? null,
  courses: parseArr(row.prep_courses_json),
  skill_gaps: parseArr(row.prep_skill_gaps_json),
  practice: parseArr(row.prep_practice_json),
  interview_insights: parseArr(row.prep_interview_insights_json),
  likely_questions: parseArr(row.prep_likely_questions_json),
  plan: parseArr(row.prep_plan_json),
  plan_markdown: row.prep_plan_markdown ?? null,
} }];
